  assert($past(a_debug_clk_select__wire_line)==3'd0||a_debug_clk_select__wire_line==3'd0||a_debug_clk_select__wire_line==$past(a_debug_clk_select__wire_line));
  assert($past(a_debug_clk_select__wire_sample)==3'd0||a_debug_clk_select__wire_sample==3'd0||a_debug_clk_select__wire_sample==$past(a_debug_clk_select__wire_sample));
  assert($past(a_debug_clk_select__conv_sample)==3'd0||a_debug_clk_select__conv_sample==3'd0||a_debug_clk_select__conv_sample==$past(a_debug_clk_select__conv_sample));
  assert($past(a_debug_bb_tap__mode)==3'd0||a_debug_bb_tap__mode==3'd0||a_debug_bb_tap__mode==$past(a_debug_bb_tap__mode));
  assert($past(a_debug_wmon_select__select)==3'd0||a_debug_wmon_select__select==3'd0||a_debug_wmon_select__select==$past(a_debug_wmon_select__select));
  assert($past(a_debug_atb__atb0)==6'd0||a_debug_atb__atb0==6'd0||a_debug_atb__atb0==$past(a_debug_atb__atb0));
  assert($past(a_debug_atb__atb1)==6'd0||a_debug_atb__atb1==6'd0||a_debug_atb__atb1==$past(a_debug_atb__atb1));
  assert($past(a_debug_clk_obs__source)==5'd0||a_debug_clk_obs__source==5'd0||a_debug_clk_obs__source==$past(a_debug_clk_obs__source));
  assert($past(a_debug_wclk_obs__source)==3'd0||a_debug_wclk_obs__source==3'd0||a_debug_wclk_obs__source==$past(a_debug_wclk_obs__source));
  assert($past(a_txpad_config__branch)==2'd0||a_txpad_config__branch==2'd0||a_txpad_config__branch==$past(a_txpad_config__branch));
  assert($past(a_usbdrive_select__branch)==2'd0||a_usbdrive_select__branch==2'd0||a_usbdrive_select__branch==$past(a_usbdrive_select__branch));
  assert($past(a_clockmux_config__rf_source)==2'd0||a_clockmux_config__rf_source==2'd0||a_clockmux_config__rf_source==$past(a_clockmux_config__rf_source));
  assert($past(a_clockmux_config__wire_source)==2'd0||a_clockmux_config__wire_source==2'd0||a_clockmux_config__wire_source==$past(a_clockmux_config__wire_source));
  assert($past(a_refinput_select__branch)==2'd0||a_refinput_select__branch==2'd0||a_refinput_select__branch==$past(a_refinput_select__branch));
  assert($past(a_termination_config__p_load)==2'd0||a_termination_config__p_load==2'd0||a_termination_config__p_load==$past(a_termination_config__p_load));
  assert($past(a_consolidation_bbfilter__direction)==2'd0||a_consolidation_bbfilter__direction==2'd0||a_consolidation_bbfilter__direction==$past(a_consolidation_bbfilter__direction));
  assert($past(a_consolidation_pll__owner)==2'd0||a_consolidation_pll__owner==2'd0||a_consolidation_pll__owner==$past(a_consolidation_pll__owner));
  assert($past(a_debug_clk_select__host_clk)==3'd0||a_debug_clk_select__host_clk==3'd0||a_debug_clk_select__host_clk==$past(a_debug_clk_select__host_clk));
 end
 // Non-vacuity: these fallback configurations are reachable through SPI writes and commits.
 always @*begin
  cover(island_on[1]&&o_debug_bb_tap__mode==3'd4);
  cover(island_on[0]&&o_debug_wtx_ext__enable==1'b1);
  cover(atb0_sw[0]&&o_core_biasgen__ena==1'b1); // ROOT_REF forced with the biasgen on (idac2 = 0)
  cover(atb0_sw[54]&&o_core_biasgen__ena==1'b1); // VBG forced with the bandgap off
 end
`endif
endmodule

module pt_mgmt(input wire rst_n,por_n,sclk,cs_n,mosi,output wire miso,miso_oe,
