 output wire[572:0]analog_cfg,output wire[255:0]debug_cfg,
 output wire[5:0]island_en,island_on,output wire[57:0]atb0_sw,atb1_sw,
 output wire[1:0]atb0_grp,output wire[4:0]atb1_grp,output wire atb0_en,atb1_en,
