 input wire[0:0]fcb_locked,
 input wire[0:0]fcb_lost,
 input wire[13:0]fcb_diff,
 input wire[15:0]fcb_count);
 wire wr_en;wire[7:0]wr_addr,rd_addr;wire[15:0]wr_data,rd_data,rd_data0,rd_data1;wire[6:0]rd_hi;
 pt_spi spi(.rst_n(rst_n),.sclk(sclk),.cs_n(cs_n),.mosi(mosi),.miso(miso),.miso_oe(miso_oe),
  .wr_en(wr_en),.wr_addr(wr_addr),.wr_data(wr_data),.rd_addr(rd_addr),.rd_data(rd_data),
  .rd_hi(rd_hi),.rd_data0(rd_data0),.rd_data1(rd_data1));
 // pt_spi presents each write from registers while count==32; the register file (and pt_memory's
 // SPI port) take it on the falling SCLK edge after the 32nd rising edge (STA: launch/capture on
 // the sclk fall edge, output budgets relative to it in integration/pt_digital_macro.sdc).
 wire sclk_regs=~sclk;
 pt_regfile regs(.rst_n(rst_n),.por_n(por_n),.sclk(sclk_regs),.wr_en(wr_en),.wr_addr(wr_addr),.wr_data(wr_data),
  .rd_addr(rd_addr),.rd_data(rd_data),.rd_hi(rd_hi),.rd_data0(rd_data0),.rd_data1(rd_data1),
  .status(status),.enable(enable),.mode8(mode8),
